#!/usr/bin/env python3
"""Process HWPX template: replace {{...}} placeholders with JSON values."""

import json
import os
import re
import shutil
import sys
import zipfile
from pathlib import Path

# Use the venv python if needed
# from lxml import etree

# Ensure lxml is available
import subprocess
subprocess.check_call([sys.executable, "-m", "pip", "install", "lxml", "-q"])
from lxml import etree

JSON_PATH = "/root/supplier_contact.json"
TEMPLATE_PATH = "/root/supplier_contact_template.hwpx"
OUTPUT_PATH = "/root/supplier_contact_ready.hwpx"

# Namespaces used in HWPX
NSMAP = {
    "hp": "http://www.hancom.co.kr/hwpml/2010/HWPML",
}

def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def extract_zip(zip_path, dest_dir):
    with zipfile.ZipFile(zip_path, "r") as z:
        z.extractall(dest_dir)

def find_xml_files(root_dir):
    xml_files = []
    for dirpath, _dirs, files in os.walk(root_dir):
        for f in files:
            if f.endswith(".xml"):
                xml_files.append(os.path.join(dirpath, f))
    return xml_files

def has_placeholder(xml_path):
    with open(xml_path, "r", encoding="utf-8") as f:
        content = f.read()
    return "{{" in content

def get_all_text_elements(tree):
    """Return a list of elements that have .text or .tail containing '{{'."""
    result = []
    for elem in tree.iter():
        if elem.text and "{{" in elem.text:
            result.append(elem)
        if elem.tail and "{{" in elem.tail:
            result.append(elem)
    return result

def replace_in_text(text, mapping):
    """Replace all {{key}} occurrences in text using mapping."""
    pattern = re.compile(r"\{\{(.*?)\}\}")

    def replacer(match):
        key = match.group(1)
        if key in mapping:
            return str(mapping[key])
        return match.group(0)

    return pattern.sub(replacer, text)

def remove_lineSegArray_from_para(para_elem):
    """Remove hp:lineSegArray and hp:lineseg children from a paragraph."""
    for child in list(para_elem):
        tag = etree.QName(child).localname
        if tag in ("lineSegArray", "lineseg"):
            para_elem.remove(child)
        else:
            # recursively remove from descendants too? spec says from <hp:p>
            pass

def process_split_placeholders(elements, mapping):
    """
    Detect placeholders split across adjacent hp:t elements.
    Example:
      <hp:t>{{</hp:t><hp:t>name</hp:t><hp:t>}}</hp:t>
    We need to merge them and put the result in the first element.
    """
    # Build a flat list of (parent, child_index, element, text) for hp:t elements
    # but easier: walk each parent and look at consecutive hp:t children
    processed_parents = set()

    for elem in elements:
        parent = elem.getparent()
        if parent is None:
            continue
        if parent in processed_parents:
            continue
        # Only process parents that are runs or similar containers containing hp:t
        children = list(parent)
        if not children:
            continue
        # Check if any child is hp:t and contains partial placeholder
        i = 0
        changed = False
        while i < len(children):
            child = children[i]
            if etree.QName(child).localname != "t":
                i += 1
                continue
            # Look for a sequence starting with "{{"
            combined_text = child.text or ""
            if "{{" not in combined_text:
                i += 1
                continue
            # Try to extend forward until we find "}}"
            j = i + 1
            while j < len(children):
                nxt = children[j]
                if etree.QName(nxt).localname != "t":
                    break
                combined_text += nxt.text or ""
                if "}}" in (nxt.text or ""):
                    break
                j += 1
            # If we found a complete placeholder in combined_text
            if re.search(r"\{\{.*?\}\}", combined_text):
                new_text = replace_in_text(combined_text, mapping)
                child.text = new_text
                # Clear intermediate elements
                for k in range(i + 1, j + 1):
                    children[k].text = ""
                    # Optionally remove them, but clearing text is safer for structure
                changed = True
                i = j + 1
            else:
                i += 1
        if changed:
            processed_parents.add(parent)

def process_xml_file(xml_path, mapping):
    parser = etree.XMLParser(remove_blank_text=False)
    tree = etree.parse(xml_path, parser)
    root = tree.getroot()

    modified_paras = set()

    # First pass: handle normal placeholders in .text and .tail
    for elem in root.iter():
        if elem.text and "{{" in elem.text:
            new_text = replace_in_text(elem.text, mapping)
            if new_text != elem.text:
                elem.text = new_text
                # Find enclosing paragraph
                para = elem
                while para is not None and etree.QName(para).localname != "p":
                    para = para.getparent()
                if para is not None:
                    modified_paras.add(para)
        if elem.tail and "{{" in elem.tail:
            new_tail = replace_in_text(elem.tail, mapping)
            if new_tail != elem.tail:
                elem.tail = new_tail
                para = elem
                while para is not None and etree.QName(para).localname != "p":
                    para = para.getparent()
                if para is not None:
                    modified_paras.add(para)

    # Second pass: handle split placeholders across multiple hp:t elements
    # Gather all hp:t elements
    t_elements = []
    for elem in root.iter():
        if etree.QName(elem).localname == "t":
            t_elements.append(elem)

    # Process groups inside the same parent
    processed_parents = set()
    for t_elem in t_elements:
        parent = t_elem.getparent()
        if parent is None or parent in processed_parents:
            continue
        children = [c for c in parent if etree.QName(c).localname == "t"]
        # Try to merge consecutive t elements that together form placeholders
        i = 0
        changed = False
        while i < len(children):
            combined = children[i].text or ""
            if "{{" not in combined:
                i += 1
                continue
            j = i + 1
            while j < len(children):
                combined += children[j].text or ""
                if "}}" in (children[j].text or ""):
                    break
                j += 1
            if re.search(r"\{\{.*?\}\}", combined):
                new_text = replace_in_text(combined, mapping)
                children[i].text = new_text
                for k in range(i + 1, j + 1):
                    children[k].text = ""
                changed = True
                # Mark enclosing para as modified
                para = parent
                while para is not None and etree.QName(para).localname != "p":
                    para = para.getparent()
                if para is not None:
                    modified_paras.add(para)
                i = j + 1
            else:
                i += 1
        if changed:
            processed_parents.add(parent)

    # Remove lineSegArray / lineseg from modified paragraphs
    for para in modified_paras:
        for child in list(para):
            if etree.QName(child).localname in ("lineSegArray", "lineseg"):
                para.remove(child)
            else:
                # Also recurse? The spec says child of <hp:p>
                # Some files might have nested lineSegArray inside run? Typically direct child.
                pass

    # Write back preserving declaration
    tree.write(xml_path, xml_declaration=True, encoding="UTF-8")
    return len(modified_paras) > 0

def repackage_hwpx(source_dir, output_path):
    with zipfile.ZipFile(output_path, "w", zipfile.ZIP_DEFLATED) as zf:
        mimetype_path = os.path.join(source_dir, "mimetype")
        if os.path.exists(mimetype_path):
            with open(mimetype_path, "rb") as f:
                zf.writestr("mimetype", f.read(), compress_type=zipfile.ZIP_STORED)
        for dirpath, _dirs, files in os.walk(source_dir):
            for f in files:
                full_path = os.path.join(dirpath, f)
                arcname = os.path.relpath(full_path, source_dir)
                if arcname == "mimetype":
                    continue
                zf.write(full_path, arcname)

def validate_output(output_path):
    extract_dir = "/tmp/hwpx_validate"
    if os.path.exists(extract_dir):
        shutil.rmtree(extract_dir)
    os.makedirs(extract_dir)
    extract_zip(output_path, extract_dir)

    checks = {
        "no_remaining_placeholders": True,
        "korean_labels_present": True,
        "static_note_unchanged": True,
        "json_values_present": True,
        "no_lineSegArray_in_modified_paras": True,
    }

    data = load_json(JSON_PATH)
    expected_values = list(data.values())
    expected_labels = ["회사명:", "담당자:", "직책:", "대표전화:", "이메일:", "주소:", "계약 시작일:", "메모: 신규 공급사 등록용"]

    for xml_path in find_xml_files(extract_dir):
        with open(xml_path, "r", encoding="utf-8") as f:
            content = f.read()
        if "{{" in content or "}}" in content:
            print(f"FAIL: Remaining placeholder in {xml_path}")
            checks["no_remaining_placeholders"] = False
        # Check expected labels
        for label in expected_labels:
            if label not in content:
                print(f"FAIL: Missing label '{label}' in {xml_path}")
                checks["korean_labels_present"] = False
        # Check JSON values present
        for val in expected_values:
            if val not in content:
                print(f"FAIL: Missing JSON value '{val}' in {xml_path}")
                checks["json_values_present"] = False
        # Check static note
        if "신규 공급사 등록용" not in content:
            print(f"FAIL: Static note missing in {xml_path}")
            checks["static_note_unchanged"] = False
        # Check no lineSegArray in paragraphs that now contain JSON values
        tree = etree.parse(xml_path)
        for para in tree.iter():
            if etree.QName(para).localname == "p":
                para_text = ""
                for desc in para.iter():
                    if desc.text:
                        para_text += desc.text
                # If paragraph contains any JSON value, ensure no lineSegArray
                for val in expected_values:
                    if val in para_text:
                        for child in para:
                            if etree.QName(child).localname in ("lineSegArray", "lineseg"):
                                print(f"FAIL: lineSegArray found in modified paragraph in {xml_path}")
                                checks["no_lineSegArray_in_modified_paras"] = False
                        break

    return checks

def main():
    data = load_json(JSON_PATH)

    work_dir = "/tmp/hwpx_work"
    if os.path.exists(work_dir):
        shutil.rmtree(work_dir)
    os.makedirs(work_dir)

    extract_zip(TEMPLATE_PATH, work_dir)

    xml_files = find_xml_files(work_dir)
    files_with_placeholders = [p for p in xml_files if has_placeholder(p)]
    print("XML files with placeholders:", files_with_placeholders)

    for xml_path in files_with_placeholders:
        modified = process_xml_file(xml_path, data)
        print(f"Processed {xml_path}, modified={modified}")

    repackage_hwpx(work_dir, OUTPUT_PATH)
    print(f"Repackaged to {OUTPUT_PATH}")

    checks = validate_output(OUTPUT_PATH)
    print("\nValidation results:")
    for check, passed in checks.items():
        status = "PASS" if passed else "FAIL"
        print(f"  {check}: {status}")

    if all(checks.values()):
        print("\nAll checks passed!")
        return 0
    else:
        print("\nSome checks failed.")
        return 1

if __name__ == "__main__":
    sys.exit(main())

